#!/bin/zsh
# Builds Phone Shi CRM.app with the command line Swift toolchain (no Xcode needed).
#   ./build_app.sh            build into mac-crm/build/
#   ./build_app.sh --install  build and copy into ~/Applications
set -euo pipefail
cd "$(dirname "$0")"

# Embed the inventory script so the app has one source of truth for it.
python3 - <<'PY'
from pathlib import Path
src = Path("Scripts/vds_inventory.py").read_text()
assert '"""##' not in src
Path("Sources/PhoneShiCRM/InventoryScript.swift").write_text(
    "// Generated by build_app.sh from Scripts/vds_inventory.py. Do not edit.\n"
    "enum InventoryScript {\n    static let source = ##\"\"\"\n" + src + "\"\"\"##\n}\n")
PY

# The native phone view runs the repo's gRPC/WebRTC viewer from this venv.
REPO="$(cd .. && pwd)"
if [[ ! -x "$REPO/.local/grpc-viewer-venv/bin/python" ]]; then
  echo "Creating $REPO/.local/grpc-viewer-venv for the native phone view (one time)..."
  python3 -m venv "$REPO/.local/grpc-viewer-venv"
  "$REPO/.local/grpc-viewer-venv/bin/pip" install -q -r "$REPO/vds_phone_view/requirements.txt"
fi

swift build -c release 2>&1 | grep -E "error|warning: unre|Compiling|Build complete" | tail -20

APP="build/Phone Shi CRM.app"
rm -rf "$APP"
mkdir -p "$APP/Contents/MacOS" "$APP/Contents/Resources"
cp .build/release/PhoneShiCRM "$APP/Contents/MacOS/PhoneShiCRM"
cat > "$APP/Contents/Info.plist" <<'PLIST'
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
  <key>CFBundleName</key><string>Phone Shi CRM</string>
  <key>CFBundleDisplayName</key><string>Phone Shi CRM</string>
  <key>CFBundleIdentifier</key><string>com.onlyrising.phoneshi.crm</string>
  <key>CFBundleExecutable</key><string>PhoneShiCRM</string>
  <key>CFBundlePackageType</key><string>APPL</string>
  <key>CFBundleShortVersionString</key><string>0.1</string>
  <key>CFBundleVersion</key><string>1</string>
  <key>LSMinimumSystemVersion</key><string>14.0</string>
  <key>LSApplicationCategoryType</key><string>public.app-category.productivity</string>
  <key>NSHighResolutionCapable</key><true/>
  <key>NSSupportsAutomaticTermination</key><false/>
</dict>
</plist>
PLIST
codesign --force --deep --sign - "$APP" >/dev/null 2>&1 || true
echo "Built $APP"

if [[ "${1:-}" == "--install" ]]; then
  mkdir -p "$HOME/Applications"
  rm -rf "$HOME/Applications/Phone Shi CRM.app"
  cp -R "$APP" "$HOME/Applications/"
  echo "Installed to ~/Applications/Phone Shi CRM.app"
fi
